# Remove Cortana Write-Host "Removing Cortana..." -ForegroundColor Cyan # Remove Cortana AppX package Get-AppxPackage -Name "Microsoft.549981C3F5F10" -ErrorAction SilentlyContinue | Remove-AppxPackage -ErrorAction SilentlyContinue Get-AppxPackage -Name "Microsoft.Cortana" -ErrorAction SilentlyContinue | Remove-AppxPackage -ErrorAction SilentlyContinue # Disable Cortana via registry Set-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\Windows Search" -Name "AllowCortana" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue Set-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\Windows Search" -Name "DisableWebSearch" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue Set-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\Windows Search" -Name "AllowSearchToUseLocation" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue Write-Host "Cortana has been removed and disabled." -ForegroundColor Green